<template>
  <section class="page">
    <header class="page__header"><div><h1 class="page__title">车辆进出记录</h1><p class="page__desc">查看车辆通行记录与放行信息</p></div><button class="button button--soft button--sm" type="button" @click="exportRecords"><span class="material-icons-outlined">download</span>导出</button></header>
    <section class="card">
      <div class="card__body card__body--filters"><div class="toolbar"><input v-model.trim="filters.keyword" class="input" type="search" placeholder="搜索车牌 / 车主 / 部门" @keyup.enter="search"><select v-model="filters.direction" class="select" aria-label="通行方向"><option value="">全部方向</option><option value="进">进</option><option value="出">出</option></select><select v-model="filters.gate" class="select" aria-label="通道"><option value="">全部通道</option><option v-for="gate in gates" :key="gate" :value="gate">{{ gate }}</option></select><select v-model="filters.passType" class="select" aria-label="放行类型"><option value="">全部放行类型</option><option v-for="passType in passTypes" :key="passType" :value="passType">{{ passType }}</option></select><div class="toolbar__right"><button class="button button--soft button--sm" type="button" @click="search"><span class="material-icons-outlined">search</span>搜索</button><button class="button button--ghost button--sm" type="button" @click="resetFilters"><span class="material-icons-outlined">restart_alt</span>重置</button></div></div></div>
      <div v-if="loading" class="state">正在加载车辆进出记录...</div><div v-else-if="errorMessage" class="state state--error">{{ errorMessage }}</div><div v-else class="table-wrap"><table class="table"><thead><tr><th>进/出图片</th><th>车牌号码</th><th>车主名称</th><th>方向</th><th>进/出时间</th><th>进/出场地点</th><th>车辆类型</th><th>放行类型</th><th>放行说明</th></tr></thead><tbody><tr v-for="record in pagedRecords" :key="record.id"><td><img v-if="record.photo" :src="record.photo" class="record-car" :alt="record.plate || '车辆'" loading="lazy"><span v-else class="record-photo" :class="record.direction === '进' ? 'record-photo--in' : 'record-photo--out'"><span class="material-icons-outlined">directions_car</span></span></td><td class="plate">{{ record.plate || "-" }}</td><td>{{ record.owner || "-" }}</td><td><span class="tag" :class="record.direction === '进' ? 'tag--blue' : 'tag--gray'">{{ record.direction }}</span></td><td class="text-sub nowrap">{{ record.time }}</td><td>{{ record.gate || "-" }}</td><td>{{ record.vehicleType || "-" }}</td><td><span class="tag" :class="passClass(record.passType)">{{ record.passType || "-" }}</span></td><td class="text-sub remark-cell">{{ record.passDesc || "-" }}</td></tr><tr v-if="pagedRecords.length === 0"><td colspan="9" class="empty">暂无记录</td></tr></tbody></table></div>
      <footer v-if="!loading && !errorMessage" class="pagination"><span class="pagination__info">共 {{ total }} 条</span><button class="page-btn" type="button" :disabled="page <= 1" @click="changePage(page - 1)"><span class="material-icons-outlined">chevron_left</span></button><button v-for="pageNumber in pageNumbers" :key="pageNumber" class="page-btn" :class="{ active: pageNumber === page }" type="button" @click="changePage(pageNumber)">{{ pageNumber }}</button><button class="page-btn" type="button" :disabled="page >= totalPages" @click="changePage(page + 1)"><span class="material-icons-outlined">chevron_right</span></button></footer>
    </section>
  </section>
</template>

<script setup lang="ts">
interface VehicleRecord { id: number; plate?: string | null; owner?: string | null; dept?: string | null; time: string; direction: string; gate?: string | null; method?: string | null; status?: string | null; photo?: string | null; vehicleType?: string | null }
interface RecordList { items: VehicleRecord[]; total: number }
const http = useHttp(); const pageSize = 8; const records = ref<VehicleRecord[]>([]); const total = ref(0); const loading = ref(true); const errorMessage = ref(""); const page = ref(1); const filters = reactive({ keyword: "", direction: "", gate: "", passType: "" });
const normalizedRecords = computed(() => records.value.map((record) => ({ ...record, passType: record.method || "未知", passDesc: record.status || "" })));
const gates = computed(() => [...new Set(normalizedRecords.value.map((record) => record.gate).filter((gate): gate is string => Boolean(gate)))]); const passTypes = computed(() => [...new Set(normalizedRecords.value.map((record) => record.passType).filter(Boolean))]);
const filteredRecords = computed(() => { const keyword = filters.keyword.toLowerCase(); return normalizedRecords.value.filter((record) => (!keyword || `${record.plate || ""}${record.owner || ""}${record.dept || ""}`.toLowerCase().includes(keyword)) && (!filters.direction || record.direction === filters.direction) && (!filters.gate || record.gate === filters.gate) && (!filters.passType || record.passType === filters.passType)); });
const totalPages = computed(() => Math.max(1, Math.ceil(total.value / pageSize))); const pageNumbers = computed(() => Array.from({ length: totalPages.value }, (_, index) => index + 1).slice(Math.max(0, page.value - 3), page.value + 2)); const pagedRecords = computed(() => normalizedRecords.value);
function passClass(passType?: string) { return passType === "车牌识别" || passType === "自动放行" ? "tag--green" : passType === "刷卡" || passType === "手动放行" ? "tag--blue" : "tag--red"; } function search() { page.value = 1; void loadRecords(); } function resetFilters() { Object.assign(filters, { keyword: "", direction: "", gate: "", passType: "" }); page.value = 1; void loadRecords(); } function changePage(nextPage: number) { page.value = Math.min(Math.max(1, nextPage), totalPages.value); void loadRecords(); }
async function loadRecords() { loading.value = true; errorMessage.value = ""; try { const result = await http.get<RecordList>("/vehicle-records", { keyword: filters.keyword || undefined, direction: filters.direction || undefined, gate: filters.gate || undefined, passType: filters.passType || undefined, page: page.value, pageSize }); records.value = result.items || []; total.value = result.total || 0; } catch (error) { errorMessage.value = (error as { statusMessage?: string }).statusMessage || "车辆进出记录加载失败"; } finally { loading.value = false; } }
function exportRecords() { const rows = [["车牌号码", "车主名称", "方向", "进出时间", "进出场地点", "车辆类型", "放行类型", "放行说明"], ...filteredRecords.value.map((record) => [record.plate || "", record.owner || "", record.direction, record.time, record.gate || "", record.vehicleType || "", record.passType || "", record.passDesc || ""])]; const csv = rows.map((row) => row.map((cell) => `"${String(cell).replaceAll('"', '""')}"`).join(",")).join("\r\n"); const link = document.createElement("a"); link.href = URL.createObjectURL(new Blob(["\ufeff" + csv], { type: "text/csv;charset=utf-8" })); link.download = "车辆进出记录.csv"; link.click(); URL.revokeObjectURL(link.href); }
watch(filteredRecords, () => { if (page.value > totalPages.value) page.value = totalPages.value; }); onMounted(loadRecords);
</script>

<style scoped>
.page{min-height:100%;padding:24px}.page__header{align-items:center;display:flex;flex-wrap:wrap;gap:12px;justify-content:space-between;margin-bottom:20px}.page__title{color:var(--text);font-size:18px;font-weight:600;margin:0}.page__desc{color:var(--text-sub);font-size:13px;margin:2px 0 0}.card{background:var(--card);border:1px solid var(--border-strong);border-radius:8px;overflow:hidden}.card__body{padding:18px}.card__body--filters{padding-bottom:4px}.toolbar{align-items:center;display:flex;flex-wrap:wrap;gap:10px;margin-bottom:14px}.toolbar .input,.toolbar .select{min-width:140px;width:auto}.toolbar__right{display:flex;gap:6px;margin-left:auto}.input,.select{background:var(--card);border:1px solid var(--border-strong);border-radius:6px;box-sizing:border-box;color:var(--text);font:inherit;height:34px;outline:none;padding:0 10px}.input:focus,.select:focus{border-color:var(--primary);box-shadow:0 0 0 2px var(--primary-soft)}.button{align-items:center;border:1px solid transparent;border-radius:6px;cursor:pointer;display:inline-flex;font:inherit;font-size:13px;gap:5px;height:32px;justify-content:center;padding:0 12px;white-space:nowrap}.button--sm{font-size:12px;height:28px;padding:0 10px}.button--soft{background:var(--primary-soft);color:var(--primary)}.button--ghost{background:var(--card);border-color:var(--border-strong);color:var(--text-sub)}.button .material-icons-outlined{font-size:16px}.table-wrap{overflow-x:auto}.table{border-collapse:collapse;font-size:13px;min-width:1050px;width:100%}.table th{background:var(--bg);border-bottom:1px solid var(--border);color:var(--text-mute);font-size:12px;font-weight:500;padding:10px 16px;text-align:left;white-space:nowrap}.table td{border-bottom:1px solid var(--border);color:var(--text);padding:9px 16px;white-space:nowrap}.table tbody tr:hover{background:var(--bg)}.record-car{border:1px solid var(--border);border-radius:6px;height:44px;object-fit:cover;width:64px}.record-photo{align-items:center;border-radius:6px;display:inline-flex;height:44px;justify-content:center;width:64px}.record-photo--in{background:#eff6ff;color:var(--primary)}.record-photo--out{background:#f4f4f5;color:var(--text-sub)}.plate{font-size:13px;font-weight:600;letter-spacing:.5px}.text-sub{color:var(--text-sub)!important}.nowrap{white-space:nowrap}.remark-cell{max-width:200px;overflow:hidden;text-overflow:ellipsis}.tag{align-items:center;border-radius:4px;display:inline-flex;font-size:12px;gap:4px;line-height:1.5;padding:2px 8px}.tag:before{background:currentColor;border-radius:50%;content:"";height:5px;width:5px}.tag--green{background:#ecfdf5;color:#059669}.tag--red{background:#fef2f2;color:#dc2626}.tag--blue{background:var(--primary-soft);color:var(--primary)}.tag--gray{background:#f4f4f5;color:var(--text-sub)}.state,.empty{color:var(--text-mute);padding:40px;text-align:center}.state--error{color:var(--red)}.pagination{align-items:center;border-top:1px solid var(--border);display:flex;flex-wrap:wrap;gap:4px;justify-content:flex-end;padding:12px 16px}.pagination__info{color:var(--text-sub);font-size:12px;margin-right:auto}.page-btn{align-items:center;background:var(--card);border:1px solid var(--border-strong);border-radius:5px;color:var(--text-sub);cursor:pointer;display:flex;font-size:12px;height:28px;justify-content:center;min-width:28px;padding:0 6px}.page-btn.active{background:var(--primary);border-color:var(--primary);color:#fff}.page-btn:disabled{cursor:not-allowed;opacity:.4}.page-btn .material-icons-outlined{font-size:16px}@media(max-width:768px){.page{padding:16px}.toolbar__right{margin-left:0}.toolbar .input,.toolbar .select,.toolbar__right{width:100%}.toolbar__right .button{flex:1}}
</style>
